function TreeNode(left, right) {
  this.left = left;
  this.right = right;
}

function bottomUpTree(depth) {
  if (depth > 0) {
    return new TreeNode(bottomUpTree(depth - 1), bottomUpTree(depth - 1));
  }
  return new TreeNode(null, null);
}

function itemCheck(node) {
  if (node.left === null) {
    return 1;
  }
  return 1 + itemCheck(node.left) + itemCheck(node.right);
}

const n = parseInt(process.argv[2], 10);
const stretchDepth = n + 1;

let stretch = bottomUpTree(stretchDepth);
process.stdout.write(
  'stretch tree of depth ' + stretchDepth + '\t check: ' + itemCheck(stretch) + '\n'
);
stretch = null;

const longLivedTree = bottomUpTree(n);

for (let depth = 4; depth <= n; depth += 2) {
  const iterations = Math.pow(2, n - depth + 4);
  let check = 0;
  for (let i = 0; i < iterations; i++) {
    check += itemCheck(bottomUpTree(depth));
