  const to = pairs[i][1].charCodeAt(0);
  complement[from] = to;
  complement[from + 32] = to;
}

const NL = 10;
const CR = 13;
const GT = 62;
const LINE = 60;

function writeRevComp(buf, start, end) {
  let count = 0;
  for (let i = start; i < end; i++) {
    const c = buf[i];
    if (c !== NL && c !== CR) count++;
  }
  if (count === 0) return;

  const lines = Math.ceil(count / LINE);
  const out = Buffer.allocUnsafe(count + lines);
  let o = 0;
  let col = 0;
  for (let i = end - 1; i >= start; i--) {
    const c = buf[i];
    if (c === NL || c === CR) continue;
    out[o++] = complement[c];
    col++;
    if (col === LINE) {
      out[o++] = NL;
      col = 0;
    }
  }
  if (col !== 0) out[o++] = NL;
  fs.writeSync(1, out, 0, o);
}

function processFasta(buf) {
  const len = buf.length;
  let i = 0;
  while (i < len) {
    if (buf[i] !== GT) {
      i++;
      continue;
    }
    let headerEnd = i;
    while (headerEnd < len && buf[headerEnd] !== NL) headerEnd++;
    const headerTo = headerEnd < len ? headerEnd + 1 : headerEnd;
    fs.writeSync(1, buf, i, headerTo - i);
    if (headerEnd < len && buf[headerEnd] !== NL) fs.writeSync(1, Buffer.from([NL]));
    i = headerTo;
    const seqStart = i;
    while (i < len && buf[i] !== GT) i++;
    writeRevComp(buf, seqStart, i);
